CREATE TABLE `pages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) NOT NULL COMMENT 'URL slug like about, home',
  `title` varchar(255) NOT NULL COMMENT 'Page title',
  `name` varchar(255) DEFAULT '' COMMENT 'Display name',
  `seo_title` varchar(255) DEFAULT NULL COMMENT 'SEO title',
  `seo_description` text COMMENT 'SEO description',
  `seo_keywords` varchar(500) DEFAULT NULL COMMENT 'SEO keywords',
  `content` longtext COMMENT 'Page content (legacy)',
  `layout` json DEFAULT NULL COMMENT 'Page layout configuration',
  `settings` json DEFAULT NULL COMMENT 'Page settings',
  `status` enum('draft','published','archived') DEFAULT 'draft',
  `published_at` timestamp NULL DEFAULT NULL COMMENT 'When page was published',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `html_content` longtext,
  `css_content` text,
  `updated_html_at` timestamp NULL DEFAULT NULL,
  `header_slug` varchar(100) DEFAULT 'header-1',
  `footer_slug` varchar(100) DEFAULT 'footer-1',
  `banner_slug` varchar(50) DEFAULT 'banner-default',
  `disabled` tinyint(1) DEFAULT '0',
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` text,
  `meta_image` varchar(500) DEFAULT NULL,
  `scheduled_for` timestamp NULL DEFAULT NULL,
  `published_layout` json DEFAULT NULL,
  `header_id` bigint unsigned DEFAULT NULL,
  `footer_id` bigint unsigned DEFAULT NULL,
  `banner_id` bigint unsigned DEFAULT NULL,
  `meta_image_id` bigint unsigned DEFAULT NULL,
  `current_revision_id` bigint unsigned DEFAULT NULL,
  `published_revision_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_pages_slug` (`slug`),
  KEY `idx_pages_status` (`status`),
  KEY `idx_pages_updated` (`updated_at`),
  KEY `idx_pages_current_revision_id` (`current_revision_id`),
  KEY `idx_pages_published_revision_id` (`published_revision_id`),
  KEY `idx_pages_header_id` (`header_id`),
  KEY `idx_pages_footer_id` (`footer_id`),
  KEY `idx_pages_banner_id` (`banner_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
